lemma S_eq_p_times_sum (k : Nat) (hk : 2 <= k) (p : Nat) :
    let n := 2 * k
    let S := (Finset.sum (Finset.range p) (fun a => (a : Rat)^n))
    let R := Finset.sum (Finset.range n) (fun j => bernoulli j * ((n + 1).choose j : Rat) * (p : Rat)^(n - j) / (n + 1))
    S = p * bernoulli n + p * R
